	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		WeatherStation
	 */
		public WeatherStation createWeatherStation( CreateWeatherStationCommand command ) {

		WeatherStation entity = new WeatherStation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWeatherStationId( command.getWeatherStationId() );
            entity.setName( command.getName() );
            entity.setStationCode( command.getStationCode() );
            entity.setCoordinates( command.getCoordinates() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of WeatherStation {0} ", entity.toString() );

		return entity;
	}

